<?php
session_start();require '../../config/db.php';if(!isset($_SESSION['admin_id'])){header('Location: ../../auth/login-admin.php');exit;}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function salvarLogoCliente($file,$clienteId,$logoAtual=''){if(empty($file['name'])||!is_uploaded_file($file['tmp_name']))return $logoAtual;$permitidos=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];$mime=mime_content_type($file['tmp_name']);if(!isset($permitidos[$mime]))throw new Exception('Envie uma logo JPG, PNG, WEBP ou GIF.');if((int)$file['size']>2*1024*1024)throw new Exception('A logo deve ter no máximo 2MB.');$dir=dirname(__DIR__,2).'/uploads/clientes/logos';if(!is_dir($dir))mkdir($dir,0755,true);$nome='cliente_'.$clienteId.'_'.time().'.'.$permitidos[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$nome))throw new Exception('Não foi possível salvar a logo.');return $nome;}$id=(int)($_GET['id']??$_POST['cliente_id']??0);if($id<=0){$_SESSION['error_msg']='Cliente não informado.';header('Location: lista-clientes.php');exit;}$stmt=$pdo->prepare('SELECT * FROM clientes WHERE id=?');$stmt->execute([$id]);$cliente=$stmt->fetch(PDO::FETCH_ASSOC);if(!$cliente){$_SESSION['error_msg']='Cliente não encontrado.';header('Location: lista-clientes.php');exit;}$erro='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if(isset($_POST['excluir_cliente'])){$pdo->prepare('DELETE FROM clientes WHERE id=?')->execute([$id]);$_SESSION['success_msg']='Cliente excluído.';header('Location: lista-clientes.php');exit;}$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$telefone=trim($_POST['telefone']??'');$senha=trim($_POST['senha']??'');if($nome===''||$email==='')throw new Exception('Nome e email são obrigatórios.');$stmt=$pdo->prepare('SELECT id FROM clientes WHERE email=? AND id<>?');$stmt->execute([$email,$id]);if($stmt->fetch())throw new Exception('Este email já está em uso por outro cliente.');$logo=salvarLogoCliente($_FILES['logo']??[],$id,$cliente['logo']??'');if($senha!==''){$hash=password_hash($senha,PASSWORD_DEFAULT);$stmt=$pdo->prepare('UPDATE clientes SET nome=?,email=?,telefone=?,senha=?,logo=? WHERE id=?');$stmt->execute([$nome,$email,$telefone,$hash,$logo,$id]);}else{$stmt=$pdo->prepare('UPDATE clientes SET nome=?,email=?,telefone=?,logo=? WHERE id=?');$stmt->execute([$nome,$email,$telefone,$logo,$id]);}$_SESSION['success_msg']='Cliente atualizado com sucesso.';header('Location: editar-cliente.php?id='.$id);exit;}catch(Throwable $e){$erro=$e->getMessage();}}$stmt=$pdo->prepare('SELECT COUNT(*) total, SUM(CASE WHEN status="finalizado" THEN 1 ELSE 0 END) finalizados, SUM(COALESCE(preco,0)) valor FROM solicitacoes WHERE cliente_id=?');$stmt->execute([$id]);$stats=$stmt->fetch(PDO::FETCH_ASSOC);?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Editar Cliente</title><link rel="stylesheet" href="../../assets/css/helpdesk-pro.css"></head><body><div class="hd-page"><header class="hd-topbar"><div class="hd-container hd-topbar-inner"><div class="hd-brand"><div class="hd-client-logo-box"><?php if(!empty($cliente['logo'])):?><img src="../../uploads/clientes/logos/<?=h(basename($cliente['logo']))?>" alt="Logo"><?php else:?>👤<?php endif;?></div><div><h1>Editar cliente</h1><p><?=h($cliente['nome'])?></p></div></div><div class="hd-user"><a class="hd-chip" href="dashboard.php">Dashboard</a><a class="hd-chip" href="lista-clientes.php">Clientes</a><a class="hd-chip" href="solicitacoes.php?id=<?=$id?>">Chamados</a></div></div></header><main class="hd-main"><div class="hd-container"><?php if($erro):?><div class="hd-alert hd-alert-error"><?=h($erro)?></div><?php endif;?><?php if(!empty($_SESSION['success_msg'])):?><div class="hd-alert hd-alert-success"><?=h($_SESSION['success_msg'])?></div><?php unset($_SESSION['success_msg']);endif;?><section class="hd-kpis"><div class="hd-kpi"><span>Chamados</span><strong><?=(int)($stats['total']??0)?></strong><small>Total do cliente</small></div><div class="hd-kpi"><span>Finalizados</span><strong><?=(int)($stats['finalizados']??0)?></strong><small>Concluídos</small></div><div class="hd-kpi"><span>Valor histórico</span><strong>R$ <?=number_format((float)($stats['valor']??0),2,',','.')?></strong><small>Serviços lançados</small></div><div class="hd-kpi"><span>ID</span><strong>#<?=$id?></strong><small>Cadastro interno</small></div></section><section class="hd-card hd-card-pad"><form method="POST" enctype="multipart/form-data" class="hd-form-grid"><input type="hidden" name="cliente_id" value="<?=$id?>"><div class="hd-field"><label class="hd-label">Nome do cliente/empresa *</label><input class="hd-input" name="nome" required value="<?=h($cliente['nome'])?>"></div><div class="hd-field"><label class="hd-label">Email *</label><input class="hd-input" type="email" name="email" required value="<?=h($cliente['email'])?>"></div><div class="hd-field"><label class="hd-label">Telefone</label><input class="hd-input" name="telefone" value="<?=h($cliente['telefone'])?>"></div><div class="hd-field"><label class="hd-label">Nova senha</label><input class="hd-input" type="password" name="senha" minlength="6" placeholder="Deixe em branco para manter"></div><div class="hd-field"><label class="hd-label">Alterar logo</label><input class="hd-input" type="file" name="logo" accept="image/*" data-logo-preview="#logoPreview"><span class="hd-ticket-meta">A logo aparece no painel do cliente e no admin.</span></div><div class="hd-field"><label class="hd-label">Logo atual/prévia</label><div class="hd-logo-preview" id="logoPreview"><?php if(!empty($cliente['logo'])):?><img src="../../uploads/clientes/logos/<?=h(basename($cliente['logo']))?>" alt="Logo"><?php else:?>Logo<?php endif;?></div></div><div class="hd-field hd-field-full"><div class="hd-actions"><button class="hd-btn hd-btn-primary" type="submit">💾 Salvar alterações</button><a class="hd-btn hd-btn-light" href="solicitacoes.php?id=<?=$id?>">Ver chamados</a><button class="hd-btn hd-btn-danger" type="submit" name="excluir_cliente" value="1" onclick="return confirm('Excluir este cliente?')">Excluir cliente</button></div></div></form></section></div></main></div><script src="../../assets/js/helpdesk-pro.js"></script></body></html>